<section class="col-lg-4"><div class="card h-100"><div class="card-body"><h2 class="h4">Equipe</h2><form method="post" class="mb-3"><input type="hidden" name="action" value="person"><input required name="name" class="form-control mb-2" placeholder="Nome"><select name="role" class="form-select mb-2"><?php foreach(['Montagem','Massa','Cozinha','Forno','Despacho','Atendimento','Estoque','Liderança','Outros'] as $role): ?><option><?= e($role) ?></option><?php endforeach ?></select><button class="btn btn-outline-primary w-100">Adicionar pessoa</button></form><form method="post"><input type="hidden" name="action" value="team"><div class="vstack gap-1"><?php foreach($people as $person): ?><label class="form-check"><input class="form-check-input" type="checkbox" name="people[]" value="<?= e($person['id']) ?>" <?= in_array($person['id'], array_column($team,'id'))?'checked':'' ?>> <?= e($person['name']) ?> <small class="text-muted">/ <?= e($person['role']) ?></small></label><?php endforeach ?></div><button class="btn btn-primary mt-3 w-100">Salvar equipe do dia</button></form></div></div></section>
